@startuml

class Ingredient {
  + Name : string
  + MeasuringUnit : string
  + QuantityInStock : float
}

class Dish {
  + Name : string
  + Identifier : int
}

class Table {
  + Identifier : int
  + MaxPeople : int
}

class Meal {
  + Date : date
  + StartTime : time
  + EndTime : time
}

class Waiter {
  + Identifier : int
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Client {
  + TaxIdentificationNumber : string
  + Name : string
  + Address : string
}

class MealDish {
  + Quantity : float
}

Dish "1" -- "*" MealDish : contains
Ingredient "1" -- "*" MealDish : used in
Dish "1" -- "*" Ingredient : composed of
"1" -- "*" MealDish : quantity

Meal "1" -- "1" Waiter : responsible
Meal "0..1" -- "1" Table : takes place at
Meal "0..1" -- "0..1" Client : consumed by
Meal "1" -- "*" MealDish : includes

@enduml

